/bin/bash -lc "node --input-type=module - <<'NODE'
import {readFileSync} from 'node:fs'
const data = JSON.parse(readFileSync('visits/87efedbc-7195-49b8-8480-42d3935f2597.json'))
for (const {action,state} of data.timeline) {
  const [visible, ...diagnostics] = state.page.split('{\"links\"')
  const desc = action.target === 'text=Read diagnostics' ? '{\"links\"' + diagnostics.join('') : ''
  console.log(state.width, action.target ?? action.op, visible.split('\\n').slice(2).join(' | '), desc)
}
console.log('error:', data.error)
NODE
nl -ba dist/view.mjs | head -37 && nl -ba dist/boot.mjs | head -20"

